Pergunta d03 ___ Observe o seguinte trecho de código em Java:

  import java.util.*;  

  class JavaColec01 {  
    /** 
     *@param args
     */  
  public static void main (String args[]){  
    ArrayList <String>list = new ArrayList<String>(); //criando arraylist
    list.add("Aluno01"); //Add objetos no arraylist  
    list.add("Aluno02");  
    list.add("Aluno03");  
    list.add("Aluno04");  
